use super::format::Format;

#[derive(Debug, Clone, Default)]
pub struct ProgressTracker {
    stages: Vec<String>,
    progress: usize,
    total: Option<usize>,
}

impl ProgressTracker {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_stage<S: Into<String>>(&mut self, stage: S) -> &mut Self {
        self.stages.push(stage.into());
        self
    }

    pub fn set_progress(&mut self, progress: usize) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: usize) -> &mut Self {
        self.total = Some(total);
        self
    }

    pub fn get_progress(&self) -> String {
        format!("{}/{}", self.progress, self.effective_total())
    }

    pub fn get_percentage(&self) -> String {
        let total = self.effective_total();
        let ratio = if total == 0 {
            0.0
        } else {
            self.progress as f32 / total as f32
        };
        Format::percentage(ratio)
    }

    fn effective_total(&self) -> usize {
        self.total.unwrap_or(self.stages.len())
    }
}

