#[derive(Debug, Clone, Default)]
pub struct ProgressBuilder {
    progress: usize,
    total: usize,
}

impl ProgressBuilder {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_progress(&mut self, progress: usize) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: usize) -> &mut Self {
        self.total = total;
        self
    }

    pub fn build(&self) -> String {
        Format::percentage(self.ratio())
    }

    fn ratio(&self) -> f32 {
        if self.total == 0 {
            0.0
        } else {
            self.progress as f32 / self.total as f32
        }
    }
}

